import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function List() {
  const [data, setData] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    axios.post(
      "https://backend.jotish.in/backend_dev/gettabledata.php",
      {
        username: "test",
        password: "123456"
      }
    )
    .then(res => {
      setData(res.data);
    })
    .catch(err => {
      console.error(err);
    });
  }, []);

  return (
    <div>
      <h2>Employee List</h2>
      <button onClick={() => navigate("/chart")}>
        View Salary Chart
      </button>
      <table border="1">
        <thead>
          <tr>
            <th>Name</th>
            <th>City</th>
            <th>Salary</th>
          </tr>
        </thead>
        <tbody>
          {data.map((item, index) => (
            <tr key={index}
                onClick={() => navigate(`/details/${index}`, { state: item })}>
              <td>{item.name}</td>
              <td>{item.city}</td>
              <td>{item.salary}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default List;
